#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_qualified_request: Mutex<Option<Drone_Lifecycle_Governor::Qualified_Request>> = Mutex::new(None);
  pub static ref IN_battery_evidence: Mutex<Option<Drone_Lifecycle_Governor::Battery_Evidence>> = Mutex::new(None);
  pub static ref IN_charge_sample: Mutex<Option<Drone_Lifecycle_Governor::Charge_Connection_Sample>> = Mutex::new(None);
  pub static ref OUT_selected_phase: Mutex<Option<Drone_Lifecycle_Governor::Lifecycle_Phase>> = Mutex::new(None);
  pub static ref OUT_decision_disposition: Mutex<Option<Drone_Lifecycle_Governor::Decision_Disposition>> = Mutex::new(None);
  pub static ref OUT_commanded_phase_report: Mutex<Option<Drone_Lifecycle_Governor::Lifecycle_Phase>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_qualified_request.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_battery_evidence.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_charge_sample.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_selected_phase.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_decision_disposition.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_commanded_phase_report.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

